create extension if not exists pgcrypto;
create table if not exists profiles(id uuid primary key references auth.users on delete cascade,telegram_id bigint unique,username text,display_name text default 'Player',photo_url text,coins bigint not null default 0 check(coins>=0),xp bigint not null default 0 check(xp>=0),level int not null default 1,streak int default 0,is_banned boolean default false,premium_until timestamptz,created_at timestamptz default now());
create table if not exists admin_users(user_id uuid primary key references auth.users on delete cascade);
create table if not exists categories(id uuid primary key default gen_random_uuid(),name text not null,name_bn text,icon text default '✦',sort_order int default 0,is_active boolean default true);
create table if not exists questions(id uuid primary key default gen_random_uuid(),category_id uuid references categories on delete set null,question_text text not null,language text default 'both',difficulty text default 'easy',options jsonb not null check(jsonb_array_length(options)=4),correct_option int not null check(correct_option between 0 and 3),explanation text,image_url text,xp_reward int default 10,is_active boolean default true,created_at timestamptz default now());
create table if not exists levels(id uuid primary key default gen_random_uuid(),level_no int unique not null,xp_required bigint default 0,question_count int default 10,time_limit int default 20,difficulty text default 'easy');
create table if not exists quiz_sessions(id uuid primary key default gen_random_uuid(),user_id uuid references profiles not null,category_id uuid references categories,mode text default 'practice',question_ids uuid[] not null,status text default 'active',score int default 0,correct_count int default 0,started_at timestamptz default now(),finished_at timestamptz);
create table if not exists quiz_answers(id uuid primary key default gen_random_uuid(),session_id uuid references quiz_sessions on delete cascade,user_id uuid references profiles,question_id uuid references questions,selected_option int,is_correct boolean,elapsed_seconds int default 0,answered_at timestamptz default now(),unique(session_id,question_id));
create table if not exists coin_transactions(id uuid primary key default gen_random_uuid(),user_id uuid references profiles,amount bigint,reason text,reference_id uuid,created_at timestamptz default now());
create table if not exists daily_tasks(id uuid primary key default gen_random_uuid(),title text,description text,image_url text,task_type text default 'quiz_count',target_value int default 1,coin_reward int default 10,xp_reward int default 0,is_active boolean default true);
create table if not exists user_tasks(id uuid primary key default gen_random_uuid(),user_id uuid references profiles,task_id uuid references daily_tasks,progress int default 0,completed_at timestamptz,reward_claimed_at timestamptz,task_date date default current_date,unique(user_id,task_id,task_date));
create table if not exists battles(id uuid primary key default gen_random_uuid(),status text default 'waiting',player_one uuid references profiles,player_two uuid references profiles,winner_id uuid references profiles,question_ids uuid[] default '{}',created_at timestamptz default now(),started_at timestamptz,finished_at timestamptz);
create table if not exists battle_players(id uuid primary key default gen_random_uuid(),battle_id uuid references battles on delete cascade,user_id uuid references profiles,score int default 0,answers jsonb default '[]',unique(battle_id,user_id));
create table if not exists referrals(id uuid primary key default gen_random_uuid(),referrer_id uuid references profiles,referred_id uuid unique references profiles,reward_paid boolean default false);
create table if not exists premium_plans(id uuid primary key default gen_random_uuid(),name text,description text,stars_price int check(stars_price>0),duration_days int default 30,is_active boolean default true);
create table if not exists payments(id uuid primary key default gen_random_uuid(),user_id uuid references profiles,plan_id uuid references premium_plans,telegram_charge_id text unique,amount int,currency text default 'XTR',status text default 'pending',created_at timestamptz default now());
create table if not exists ad_settings(id uuid primary key default gen_random_uuid(),network text,placement text,publisher_id text,ad_unit_id text,is_active boolean default false,unique(network,placement));
create table if not exists notifications(id uuid primary key default gen_random_uuid(),title text,body text,image_url text,sent_count int default 0,created_at timestamptz default now());
create table if not exists app_settings(key text primary key,value jsonb default '{}'::jsonb);
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from admin_users where user_id=auth.uid())$$;
create or replace function public.new_profile() returns trigger language plpgsql security definer set search_path=public as $$begin insert into profiles(id,display_name) values(new.id,coalesce(new.raw_user_meta_data->>'display_name','Player')) on conflict do nothing;return new;end$$;
drop trigger if exists auth_profile_create on auth.users;create trigger auth_profile_create after insert on auth.users for each row execute procedure new_profile();
-- Enable RLS on all application tables
 do $$declare t text;begin foreach t in array array['profiles','admin_users','categories','questions','levels','quiz_sessions','quiz_answers','coin_transactions','daily_tasks','user_tasks','battles','battle_players','referrals','premium_plans','payments','ad_settings','notifications','app_settings'] loop execute format('alter table %I enable row level security',t);end loop;end$$;
create policy profile_read on profiles for select using(id=auth.uid() or is_admin());create policy profile_update on profiles for update using(id=auth.uid() or is_admin()) with check(id=auth.uid() or is_admin());
create policy admin_read on admin_users for select using(user_id=auth.uid() or is_admin());
create policy catalog_read_categories on categories for select using(is_active or is_admin());create policy catalog_admin_categories on categories for all using(is_admin()) with check(is_admin());
create policy catalog_read_questions on questions for select using(is_active or is_admin());create policy catalog_admin_questions on questions for all using(is_admin()) with check(is_admin());
create policy catalog_read_levels on levels for select using(true);create policy catalog_admin_levels on levels for all using(is_admin()) with check(is_admin());
create policy sessions_own_read on quiz_sessions for select using(user_id=auth.uid() or is_admin());create policy sessions_admin on quiz_sessions for all using(is_admin()) with check(is_admin());
create policy answers_own_read on quiz_answers for select using(user_id=auth.uid() or is_admin());create policy answers_admin on quiz_answers for all using(is_admin()) with check(is_admin());
create policy coins_own_read on coin_transactions for select using(user_id=auth.uid() or is_admin());create policy coins_admin on coin_transactions for all using(is_admin()) with check(is_admin());
create policy tasks_read on daily_tasks for select using(is_active or is_admin());create policy tasks_admin on daily_tasks for all using(is_admin()) with check(is_admin());create policy user_tasks_read on user_tasks for select using(user_id=auth.uid() or is_admin());create policy user_tasks_admin on user_tasks for all using(is_admin()) with check(is_admin());
create policy battles_read on battles for select using(player_one=auth.uid() or player_two=auth.uid() or is_admin());create policy battles_admin on battles for all using(is_admin()) with check(is_admin());create policy battle_players_read on battle_players for select using(user_id=auth.uid() or is_admin());create policy battle_players_admin on battle_players for all using(is_admin()) with check(is_admin());
create policy referrals_read on referrals for select using(referrer_id=auth.uid() or referred_id=auth.uid() or is_admin());create policy referrals_admin on referrals for all using(is_admin()) with check(is_admin());
create policy plans_read on premium_plans for select using(is_active or is_admin());create policy plans_admin on premium_plans for all using(is_admin()) with check(is_admin());create policy payments_read on payments for select using(user_id=auth.uid() or is_admin());create policy payments_admin on payments for all using(is_admin()) with check(is_admin());
create policy ad_admin on ad_settings for all using(is_admin()) with check(is_admin());create policy notification_admin on notifications for all using(is_admin()) with check(is_admin());create policy settings_read on app_settings for select using(key='public' or is_admin());create policy settings_admin on app_settings for all using(is_admin()) with check(is_admin());
